commands:
make check 2>&1 | tail -3 && make lint && awk 'length > 72 {print FILENAME": "FNR": "length}' hourglass/rounding.py tests/test_rounding.py && echo "--- literals (non 0/1):" && python3 -I -c '
import ast,sys
for f in sys.argv[1:]:
    t=ast.parse(open(f).read())
    for n in ast.walk(t):
        if isinstance(n,ast.Constant) and type(n.value) in (int,float) and n.value not in (0,1):
            print(f,n.lineno,n.value)
        if isinstance(n,(ast.FunctionDef,)):
            print(f,n.name,"lines",n.end_lineno-n.lineno+1)
        if isinstance(n,ast.Name) and isinstance(n.ctx,ast.Store) and len(n.id)<4:
            print(f,"short name",n.id,n.lineno)
        if isinstance(n,ast.arg) and len(n.arg)<4:
            print(f,"short arg",n.arg)
' hourglass/rounding.py tests/test_rounding.py && head -3 hourglass/rounding.py tests/test_rounding.py

